/**
 * Refuses when the plan has no slot for one more live project. Archived
 * projects do not hold a slot, so this guards both create and restore.
 */
async function assertProjectSlotFree(
  org: Organization,
  verb: string,
): Promise<void> {
  const used = await projectRepo.countProjects(org.id);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "projects")} projects; upgrade to ${verb} another`,
    );
  }
}

/** True when applying `input` to `project` would change a stored field. */
function changesProject(project: Project, input: UpdateProjectInput): boolean {
  const fields = [
    "name",
    "description",
    "visibility",
    "status",
    "leadId",
    "color",
    "targetDate",
  ] as const;
  return fields.some(
    (field) => input[field] !== undefined && input[field] !== project[field],
  );
}

