export default defineConfig({
  resolve: { alias: { "@": "$W/src", "@fixtures": "$W/tests/server/_support" } },
  test: { environment: "node", include: ["/tmp/projfix-check/*.test.ts"], root: "/tmp/projfix-check" },
});
