cat > /tmp/projfix-check/scenarios.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("@fixtures/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import * as projectService from "@/server/services/project-service";
import { registerUsageListeners, recomputeUsage } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "@fixtures/fixtures";

const input = (orgId: any, name: string, slug: string, key: string) => ({
  orgId, name, slug, key, description: null, visibility: "org" as const, leadId: null, color: "#6366f1", targetDate: null,
});
let cleanup: () => void; let off: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); off = registerUsageListeners(); });
afterAll(() => { off(); cleanup(); });

describe("reports", () => {
  it("1: archiving frees a slot", async () => {
    const t = await createTenant("r1", "free");
    await projectService.createProject(t.actors.owner, input(t.org.id, "Second", "second", "SEC"));
    await expect(projectService.createProject(t.actors.owner, input(t.org.id, "Third", "third", "THI"))).rejects.toThrow(/allows 2 projects/);
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    const p = await projectService.createProject(t.actors.owner, input(t.org.id, "Third", "third", "THI"));
    expect(p.archivedAt).toBeNull();
  });
  it("2: look-alike keys", async () => {
    const t = await createTenant("r2", "growth");
    const a = await projectService.createProject(t.actors.owner, input(t.org.id, "Web Vendors", "web-vendors", "WV"));
    const b = await projectService.createProject(t.actors.owner, input(t.org.id, "Web Visitors", "web-visitors", "WV"));
    expect(a.key).toBe("WV"); expect(b.key).toBe("WV2");
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: a.id, archiveIssues: true });
    const c = await projectService.createProject(t.actors.owner, input(t.org.id, "Web Views", "web-views", "WV"));
    expect(c.key).toBe("WV3");
    const d = await projectService.createProject(t.actors.owner, input(t.org.id, "Plat again", "plat-again", "PLAT"));
    expect(d.key).toBe("PLA2");
    const other = await createTenant("r2b", "growth");
    const e = await projectService.createProject(other.actors.owner, input(other.org.id, "Web Vendors", "web-vendors", "WV"));
    expect(e.key).toBe("WV");
  });
  it("3: archived address stays reserved", async () => {
    const t = await createTenant("r3", "growth");
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    const p = await projectService.createProject(t.actors.owner, input(t.org.id, "Platform", "platform", "PLT"));
    expect(p.slug).toBe("platform-2");
    const r = await projectService.restoreProject(t.actors.owner, t.org.id, t.project.id);
    expect(r.slug).toBe("platform");
  });
  it("4: restore respects plan, meter follows", async () => {
    const t = await createTenant("r4", "free");
    await recomputeUsage(t.org.id);
    await projectService.createProject(t.actors.owner, input(t.org.id, "Second", "second", "SEC"));
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(1);
    await projectService.createProject(t.actors.owner, input(t.org.id, "Third", "third", "THI"));
    const events: unknown[] = []; const o = subscribe("project.restored", (p) => { events.push(p); });
    await expect(projectService.restoreProject(t.actors.owner, t.org.id, t.project.id)).rejects.toThrow(/allows 2 projects/);
    o();
    expect(events).toHaveLength(0);
    expect((await projectRepo.findProjectById(t.org.id, t.project.id))?.archivedAt).not.toBeNull();
    expect((await usageRepo.getUsage(t.org.id)).projectsUsed).toBe(2);
    const g = await createTenant("r4g", "growth");
    await projectService.archiveProject(g.actors.owner, { orgId: g.org.id, projectId: g.project.id, archiveIssues: false });
    const before = (await usageRepo.getUsage(g.org.id)).projectsUsed;
    await projectService.restoreProject(g.actors.owner, g.org.id, g.project.id);
    const after = (await usageRepo.getUsage(g.org.id)).projectsUsed;
    expect(after).toBe(before + 1);
    expect((await recomputeUsage(g.org.id)).projectsUsed).toBe(after);
  });
  it("5: restoring a live project is refused", async () => {
    const t = await createTenant("r5", "growth");
    const events: unknown[] = []; const o = subscribe("project.restored", (p) => { events.push(p); });
    await expect(projectService.restoreProject(t.actors.owner, t.org.id, t.project.id)).rejects.toThrow(/not archived/);
    o(); expect(events).toHaveLength(0);
  });
  it("6: status", async () => {
    const t = await createTenant("r6", "growth");
    const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id));
    const paused = await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "paused" });
    expect(paused.status).toBe("paused");
    const list = await projectService.listProjects(t.actors.owner, { orgId: t.org.id, status: "paused", limit: 10 } as any);
    expect(list.items.map((x) => x.project.id)).toContain(t.project.id);
    await expect(issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id))).rejects.toThrow(/paused/);
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "in_progress" });
    await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "still workable", parentId: null } as any);
    await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "completed", name: "Renamed" })).rejects.toThrow(/open issues/);
    const still = await projectRepo.findProjectById(t.org.id, t.project.id);
    expect(still?.status).toBe("paused"); expect(still?.name).not.toBe("Renamed");
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "done" });
    const done = await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(done.status).toBe("completed");
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "todo" });
    const again = await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "completed" });
    expect(again).toEqual(done);
    await expect(projectService.updateProject(t.actors.viewer, { orgId: t.org.id, projectId: t.project.id, status: "active" })).rejects.toThrow();
    const active = await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "active" });
    expect(active.status).toBe("active");
    await projectService.archiveProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: true });
    await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: t.project.id, status: "paused" })).rejects.toThrow(/archived/);
  });
});
EOF
